import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"hnl_engine_exec_tree_walk","description":"","frontmatter":{},"headers":[],"relativePath":"api/engine-exec-tree-walk/hnl_engine_exec_tree_walk/index.md","filePath":"api/engine-exec-tree-walk/hnl_engine_exec_tree_walk/index.md"}`),a={name:`api/engine-exec-tree-walk/hnl_engine_exec_tree_walk/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="hnl-engine-exec-tree-walk" tabindex="-1">hnl_engine_exec_tree_walk <a class="header-anchor" href="#hnl-engine-exec-tree-walk" aria-label="Permalink to “hnl_engine_exec_tree_walk”">​</a></h1><h1 id="hnl-engine-exec-tree-walk-1" tabindex="-1">hnl-engine-exec-tree-walk <a class="header-anchor" href="#hnl-engine-exec-tree-walk-1" aria-label="Permalink to “hnl-engine-exec-tree-walk”">​</a></h1><p>The <strong>reference interpreter</strong> for the eval operation (ADR-0044 §3, §4, ADR-0052). Interprets the arrow-calculus [<code>handl_language::Term</code>] kernel directly via tree-walking: it looks up <code>lang.eval[node.kind]</code> → [<code>handl_language::EvalSchemeDef</code>] → [<code>Term</code>], and interprets the scheme. It is entirely data-driven.</p><h2 id="value-shapes" tabindex="-1">Value shapes <a class="header-anchor" href="#value-shapes" aria-label="Permalink to “Value shapes”">​</a></h2><p>The arrow-calculus combinators operate on a few tagged JSON value shapes:</p><ul><li><strong>Pair</strong> (<code>first</code>): <code>{&quot;__pair__&quot;: [a, b]}</code>. <code>first inner</code> runs <code>inner</code> on <code>a</code> and carries <code>b</code> through, producing <code>{&quot;__pair__&quot;: [inner(a), b]}</code>.</li><li><strong>Either</strong> (<code>Choice</code> / <code>tag</code>): <code>{&quot;__either__&quot;: &quot;left&quot;|&quot;right&quot;, &quot;value&quot;: v}</code>. <code>Choice { l, r }</code> routes a <code>left</code> Either to <code>l</code> and a <code>right</code> Either to <code>r</code>. The <code>tag</code> native op converts a truthy value into a <code>left</code> Either and a falsy value into a <code>right</code> Either (the <code>Branch</code> lowering: <code>c &gt;&gt;&gt; arr tag &gt;&gt;&gt; Choice(t, e)</code>).</li><li><strong>Arrow-value</strong> (<code>App</code>): <code>{&quot;__arrow__&quot;: true, &quot;params&quot;: [...], &quot;body_def&quot;: {&quot;__ast__&quot;: &amp;lt;arena&gt;}, &quot;binds&quot;: {...}, &quot;handlers&quot;: [...]}</code> — self-contained serializable data (ADR-0106). <code>App</code> evaluates the callee; if it is a string naming a registered host function, dispatches to it; otherwise applies the arrow (install <code>binds</code> as the captured root, bind params, eval the <code>body_def</code> arena, restore).</li></ul><h2 id="payload-convention" tabindex="-1"><code>$payload</code> convention <a class="header-anchor" href="#payload-convention" aria-label="Permalink to “$payload convention”">​</a></h2><p>When a <code>proj_env</code> or <code>extend_env</code> literal name is the string <code>&quot;$payload&quot;</code>, the engine reads the actual name from the current node&#39;s payload:</p><ul><li><code>proj_env &quot;$payload&quot;</code> → reads <code>node.payload</code> as a string (the variable name).</li><li><code>extend_env &quot;$payload&quot;</code> → reads <code>node.payload[&quot;name&quot;]</code> as a string (the bind name).</li></ul><h2 id="no-scheme-fallback" tabindex="-1">No-scheme fallback <a class="header-anchor" href="#no-scheme-fallback" aria-label="Permalink to “No-scheme fallback”">​</a></h2><p>If a node kind has no eval scheme in the <code>Language</code>, the engine returns <code>node.payload</code> as the value directly. This handles literal nodes (e.g. a <code>&quot;lit&quot;</code> node whose payload is <code>42</code>). <code>foreign.&lt;name&gt;</code> kinds dispatch to the host function <code>&lt;name&gt;</code> with evaluated children.</p><h2 id="loop-semantics" tabindex="-1">Loop semantics <a class="header-anchor" href="#loop-semantics" aria-label="Permalink to “Loop semantics”">​</a></h2><p>[<code>Term::Loop</code>] implements <strong>causal/strict</strong> feedback (ADR-0052). The handler seeds <code>State</code> with [<code>Value::Null</code>], constructs the pair <code>(In, State)</code>, and evaluates <code>body</code> with that pair as <code>incoming</code>. The body&#39;s result shape selects one of two modes:</p><ul><li><strong>Single-step.</strong> The body returns a <strong>pair</strong> <code>(Out, NewState)</code>; <code>Loop</code> returns <code>Out</code>.</li><li><strong>Multi-step (Either-based).</strong> The body returns an <strong>Either</strong>: <code>left(out)</code> → done; <code>right(new_state)</code> → re-run with <code>pair(original_input, new_state)</code>. A max-iteration guard (100_000) prevents infinite loops.</li></ul><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="hnl-engine-exec-tree-walk-2" tabindex="-1"><a href="./hnl_engine_exec_tree_walk.html"><code>hnl_engine_exec_tree_walk</code></a> <a class="header-anchor" href="#hnl-engine-exec-tree-walk-2" aria-label="Permalink to “hnl_engine_exec_tree_walk”">​</a></h3><p><em>1 module, 1 trait, 10 constants, 10 structs, 22 functions</em></p><h3 id="scopestack" tabindex="-1"><a href="./ScopeStack.html"><code>ScopeStack</code></a> <a class="header-anchor" href="#scopestack" aria-label="Permalink to “ScopeStack”">​</a></h3><p><em>1 function</em></p><h3 id="treewalkengine" tabindex="-1"><a href="./TreeWalkEngine.html"><code>TreeWalkEngine</code></a> <a class="header-anchor" href="#treewalkengine" aria-label="Permalink to “TreeWalkEngine”">​</a></h3><p><em>15 functions</em></p><h3 id="valuemodel" tabindex="-1"><a href="./ValueModel.html"><code>ValueModel</code></a> <a class="header-anchor" href="#valuemodel" aria-label="Permalink to “ValueModel”">​</a></h3><p><em>2 functions</em></p>`,23)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};